// Get report_id from trigger
const reportId = $('Encore WF3P Webhook').first().json.body.report_id;
const __lr = $('Get Report Language').first().json; const __lang = ((__lr && __lr.language) === 'nl') ? 'nl' : 'en';


// Subheaders to convert to h5 tags (must match the T3 Careers Prompt).
// "## " headers are converted whatever their text; this list only rescues
// headers the model wrote as a bold line instead.
const CAREER_SUBHEADERS_ALL = {
  en: ["Overview", "Why this fits you", "What you'll actually do", "How people get in", "Your first step", "The Reality Check", "The practical stuff", "How AI will impact this role", "Future-proof skills"],
  nl: ["Overzicht", "Waarom dit bij u past", "Wat u concreet gaat doen", "Zo komt u binnen", "Uw eerste stap", "Waar u rekening mee moet houden", "De praktische kant", "AI-impact op deze rol", "Toekomstbestendige vaardigheden"]
};
const CAREER_SUBHEADERS = CAREER_SUBHEADERS_ALL[__lang];

// Pull the machine-readable comparison JSON out of a career chunk.
// The model appends it as a fenced ```json block, last thing in the career.
// Returns { metadata, cleanedText }. On ANY failure metadata is null, so a
// missing or malformed block degrades gracefully and never breaks the report.
function extractMetadata(careerText) {
  let raw = null;
  let matchedBlock = null;

  // Preferred: a fenced code block (```json ... ``` or ``` ... ```).
  // Take the LAST one — the comparison block is the last thing in the career.
  const fenceRegex = /```(?:json)?\s*([\s\S]*?)```/gi;
  let m;
  while ((m = fenceRegex.exec(careerText)) !== null) {
    raw = m[1];
    matchedBlock = m[0];
  }

  // Fallback: a bare { ... } span (model dropped the fence).
  if (raw === null) {
    const bm = careerText.match(/\{[\s\S]*\}/);
    if (bm) {
      raw = bm[0];
      matchedBlock = bm[0];
    }
  }

  if (raw === null) {
    return { metadata: null, cleanedText: careerText.replace(/\n+\s*\*{0,2}More details[^\n]*\s*$/i, '').trim() };
  }

  let metadata = null;
  try {
    metadata = JSON.parse(raw.trim());
  } catch (e) {
    metadata = null;
  }

  const cleanedText = careerText.replace(matchedBlock, '').replace(/\n+\s*\*{0,2}More details[^\n]*\s*$/i, '').trim();
  return { metadata, cleanedText };
}

// Function to convert subheaders to h5 tags
function formatSubheaders(content) {
  let formatted = content;

  // Convert ## headers to h5 tags
  formatted = formatted.replace(/^## (.+)$/gm, '<h5>$1</h5>');

  // Also convert bold-only subheaders from the predefined list
  CAREER_SUBHEADERS.forEach(subheader => {
    const regex = new RegExp(`(^|\\n)\\*\\*${subheader}\\*\\*:?\\s*`, 'gi');
    formatted = formatted.replace(regex, `$1<h5>${subheader}</h5>\n\n`);
  });

  // Clean up any leftover markdown bold markers
  formatted = formatted.replace(/\*\*(.*?)\*\*/g, '$1');

  return formatted.trim();
}

// Function to extract career metadata and clean content
function parseCareer(careerText) {
  const lines = careerText.trim().split('\n');
  let title = '';
  let alternateTitles = '';
  let companySizeType = '';
  let score = null;
  let contentStartIndex = 0;

  // Parse first few lines for metadata
  for (let i = 0; i < Math.min(15, lines.length); i++) {
    const line = lines[i].trim();

    // Extract title - ONLY single # (career title), not ## (subheaders)
    if (line.match(/^# [^#]/) ) {
      title = line.replace(/^# /, '').trim();
      contentStartIndex = i + 1;
    } else if (line.match(/^-?\s*Title:/i)) {
      title = line.replace(/^-?\s*Title:\s*/i, '').trim();
      contentStartIndex = Math.max(contentStartIndex, i + 1);
    }

    // Extract alternate titles
    if (line.match(/^\*\*Alternative titles:\*\*/i) || line.match(/^-?\s*\*?Alternate titles:/i)) {
      const altMatch = line.match(/\*\*Alternative titles:\*\* (.+?) \| \*\*At:\*\* (.+)/);
      if (altMatch) {
        alternateTitles = altMatch[1].trim();
        companySizeType = altMatch[2].trim();
        contentStartIndex = Math.max(contentStartIndex, i + 1);
      } else {
        alternateTitles = line
          .replace(/^-?\s*\*?\*?Alternative titles:\*?\*?\s*/i, '')
          .replace(/^-?\s*\*?Alternate titles:\*?\s*/i, '')
          .replace(/\*/g, '')
          .trim();
        contentStartIndex = Math.max(contentStartIndex, i + 1);
      }
    }

    // Extract company size - standalone "At:" line
    if (line.match(/^-?\s*\*?\*?At:\*?\*?\s*/i) && !line.match(/Alternative titles/i)) {
      companySizeType = line
        .replace(/^-?\s*\*?\*?At:\*?\*?\s*/i, '')
        .replace(/\*\*/g, '')
        .trim();
      contentStartIndex = Math.max(contentStartIndex, i + 1);
    }

    // Extract compatibility score
    const scoreMatch = line.match(/\*?\*?Compatibility score:\s*(\d+)\/100\*?\*?/i);
    if (scoreMatch) {
      score = parseInt(scoreMatch[1], 10);
      contentStartIndex = Math.max(contentStartIndex, i + 1);
    }
  }

  // Skip empty lines after metadata
  while (contentStartIndex < lines.length && lines[contentStartIndex].trim() === '') {
    contentStartIndex++;
  }

  // Get remaining content and format subheaders
  const rawContent = lines.slice(contentStartIndex).join('\n').trim();
  const formattedContent = formatSubheaders(rawContent);

  return {
    title: `<h3><strong>${title || 'Career Option'}</strong></h3>`,
    alternate_titles: alternateTitles ? `<strong>Alternate titles:</strong> ${alternateTitles}` : '',
    company_size_type: companySizeType ? `<h4><strong>${companySizeType}</strong></h4>` : '',
    content: formattedContent,
    score: score
  };
}

// Split by separator
const splitCareers = fullText.split('---CAREER_SPLIT---');

// Validate we have 3 parts
if (splitCareers.length !== 3) {
  throw new Error(`Expected 3 careers but found ${splitCareers.length}`);
}

// Pull the comparison JSON out of each chunk BEFORE parsing the prose,
// so the raw JSON never lands in the rendered content.
const meta1 = extractMetadata(splitCareers[0]);
const meta2 = extractMetadata(splitCareers[1]);
const meta3 = extractMetadata(splitCareers[2]);

// The comparison JSON is the last thing the model writes. If direction 3
// has none, the output was cut off (token limit): fail loudly so the error
// workflow alerts us, instead of saving a half-finished direction.
if (!meta3.metadata) {
  throw new Error('Top 3 output looks cut off: direction 3 has no comparison JSON. Check the model token limit and rerun this report.');
}

// Parse each career from the cleaned (JSON-stripped) text
const career1 = parseCareer(meta1.cleanedText);
const career2 = parseCareer(meta2.cleanedText);
const career3 = parseCareer(meta3.cleanedText);

// Map to structured output with all required fields.
// `metadata` is picked up automatically by the autoMap Supabase insert.
return [
  {
    json: {
      title: career1.title,
      alternate_titles: career1.alternate_titles,
      company_size_type: career1.company_size_type,
      content: career1.content,
      score: career1.score,
      metadata: meta1.metadata,
      report_id: reportId,
      section_type: "top_career_1",
      order_number: 1,
      language: __lang
    }
  },
  {
    json: {
      title: career2.title,
      alternate_titles: career2.alternate_titles,
      company_size_type: career2.company_size_type,
      content: career2.content,
      score: career2.score,
      metadata: meta2.metadata,
      report_id: reportId,
      section_type: "top_career_2",
      order_number: 2,
      language: __lang
    }
  },
  {
    json: {
      title: career3.title,
      alternate_titles: career3.alternate_titles,
      company_size_type: career3.company_size_type,
      content: career3.content,
      score: career3.score,
      metadata: meta3.metadata,
      report_id: reportId,
      section_type: "top_career_3",
      order_number: 3,
      language: __lang
    }
  }
];

// Prep runner up data + build RPC body for Pull Runner up
const trigger = $('Encore WF3P Webhook').first().json.body;
const careers = trigger.runner_up_careers || [];
const input_careers_text = careers.map(c => ({
  career_title: c.career_title,
  company_size_type: c.company_size_type
}));
return [{ json: {
  runner_up: careers,
  rpc_body: JSON.stringify({ input_careers_text })
} }];

// Combine all items into one item
const allItems = $input.all();
const allCareers = allItems.map(item => item.json);

return [{ 
  json: { 
    allCareers: allCareers,
    careerCount: allCareers.length 
  } 
}];

// Parse Runner-Up Careers (Markdown format with CAREER_SPLIT delimiter)
const input = $input.first().json.text;

// Get report_id from the same node that Split Top3 uses
const reportId = $('Encore WF3P Webhook').first().json.body.report_id;
const __lr = $('Get Report Language').first().json; const __lang = ((__lr && __lr.language) === 'nl') ? 'nl' : 'en';

// GUARD (2026-07-05): if no runner-up careers came in from '4-10 only', the
// upstream pool was empty. Do NOT parse the LLM output (it hallucinates a
// "the list is empty" complaint). Emit one clean, controlled placeholder row.
const __ru = ($('4-10 only').first().json.runner_up) || [];
if (!Array.isArray(__ru) || __ru.length === 0) {
  const __msg = __lang === 'nl'
    ? 'Er zijn geen andere richtingen die hoog genoeg scoorden. Uw sterkste richtingen staan in uw top 3 hierboven.'
    : 'No other directions scored high enough to include. Your strongest directions are in your top 3 above.';
  return [{ json: {
    title: '',
    alternate_titles: '',
    company_size_type: '',
    content: '<p>' + __msg + '</p>',
    score: null,
    report_id: reportId,
    metadata: { empty: true },
    section_type: 'runner_ups',
    order_number: 1,
    language: __lang
  } }];
}


// Split by the delimiter
const careerBlocks = input.split('---CAREER_SPLIT---').map(block => block.trim()).filter(Boolean);

const results = careerBlocks.map((block, index) => {
  // Extract career title (first # heading, not ## subheaders)
  const titleMatch = block.match(/^# ([^#].+)$/m);
  const career_title = titleMatch ? titleMatch[1].trim() : `Career ${index + 1}`;

  // Extract alternative titles and company size
  const altTitlesMatch = block.match(/\*\*Alternative titles:\*\* (.+?) \| \*\*At:\*\* (.+)/);
  const alternate_titles = altTitlesMatch ? altTitlesMatch[1].trim() : '';
  const company_size_type = altTitlesMatch ? altTitlesMatch[2].trim() : '';

  // Extract compatibility score
  const scoreMatch = block.match(/\*\*Compatibility score: (\d+)\/100\*\*/);
  const score = scoreMatch ? parseInt(scoreMatch[1], 10) : null;

  const moveMatch = block.match(/<!--move:(.*?)-->/i);
  const move = moveMatch ? moveMatch[1].trim() : null;

  // Build content language-agnostically: from the first "## " subheader
  // onward, drop any trailing "**More details" footer, and convert every
  // "## X" header to <h5>X</h5>. Works for English and Dutch headers alike.
  let __body = block;
  const __fh = __body.search(/^##\s+/m);
  if (__fh >= 0) __body = __body.slice(__fh);
  __body = __body.split(/\n\*\*More details/)[0];
  const sections = __body.replace(/^##\s+(.+?)\s*$/gm, '<h5>$1</h5>').replace(/<!--move:.*?-->/gi, '').trim();

  // Return one item per career (matches report_sections table structure)
  return {
    json: {
      title: `<h3><strong>${career_title}</strong></h3>`,
      alternate_titles: alternate_titles ? `<strong>Alternate titles:</strong> ${alternate_titles}` : '',
      company_size_type: company_size_type ? `<h4><strong>${company_size_type}</strong></h4>` : '',
      content: sections,
      score: score,
      report_id: reportId,
      metadata: move ? { move } : null,
      section_type: "runner_ups",
      order_number: index + 1,
      language: __lang
    }
  };
});

return results;

// Prepare data for the "your idea" step (Dream Job Feasibility).
// Encore v2: the idea section only runs when the person wrote something in
// 3.5. has_idea comes from WF1P's structured facts (the raw answer); for
// reports without facts it falls back to the "Their Idea" section of the
// profile summary. The "Has idea?" node routes on it.
const trigger = $('Encore WF3P Webhook').first().json.body;
const facts = trigger.facts || null;

let hasIdea = false;
let idea = '';
if (facts && typeof facts.has_idea === 'boolean') {
  hasIdea = facts.has_idea;
  idea = facts.idea || '';
} else {
  const t = trigger.interests_history_text || '';
  const m = t.match(/###\s*Their Idea\s*\n([\s\S]*?)(?=\n###|$)/i);
  const block = m ? m[1].trim() : '';
  hasIdea = !!block && !/no idea named/i.test(block) && !/^not provided/i.test(block);
  idea = hasIdea ? block : '';
}

return [{
  json: {
    has_idea: hasIdea,
    'Their idea': idea,
    'Top 3 careers': trigger.top_3_careers_str,
    'Runner up careers': trigger.runner_up_careers_str,
    'Outside box careers': trigger.outside_box_careers_str
  }
}];

// Get report_id from upstream node
const reportId = $('Encore WF3P Webhook').first().json.body.report_id;

// Get the dream jobs text from the upstream node
const fullText = $json.text;

// Subheaders to convert to h5 tags
const __lr = $('Get Report Language').first().json;
const __lang = ((__lr && __lr.language) === 'nl') ? 'nl' : 'en';
// Encore v2 "your idea" headings (must match the Dream Job Feasibility prompt)
const DREAM_JOB_SUBHEADERS_ALL = {
  en: ["Overview","Our honest view","How it fits your week","A small version to start with","What to know before you start","How to start"],
  nl: ["Overzicht","Onze eerlijke kijk","Hoe het in uw week past","Uw idee in het klein","Wat u vooraf moet weten","Zo begint u"]
};
const DREAM_JOB_SUBHEADERS = DREAM_JOB_SUBHEADERS_ALL[__lang];

function formatDreamJobContent(content) {
  let formatted = content;

  DREAM_JOB_SUBHEADERS.forEach(subheader => {
    /**
     * Updated Regex:
     * 1. Looks for the subheader at the start of the string or after a newline
     * 2. Allows for optional Markdown stars (**)
     * 3. Allows for an optional colon (:)
     * 4. Ensures it matches the whole line to avoid replacing the word mid-sentence
     */
    const regex = new RegExp(`(^|\\n)\\*?\\*?${subheader}\\*?\\*?:?\\s*(\\n|$)`, 'gi');
    formatted = formatted.replace(regex, `$1<h5>${subheader}</h5>\n\n`);
  });

  // Convert markdown bold to <strong> — covers the feasibility rating,
  // which the prompt now bolds in full.
  formatted = formatted.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

  return formatted.trim();
}

function parseDreamJob(content) {
  const lines = content.trim().split('\n');
  let title = '';
  let contentStartIndex = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    // Match ## Title or just "Chief Product Officer" if it's the very first line
    if (line.match(/^##\s*.+$/) || (i === 0 && line.length > 0)) {
      title = line.replace(/^##\s*/, '').trim();
      contentStartIndex = i + 1;
      break;
    }
  }

  while (contentStartIndex < lines.length && lines[contentStartIndex].trim() === '') {
    contentStartIndex++;
  }

  const rawContent = lines.slice(contentStartIndex).join('\n').trim();
  const formattedContent = formatDreamJobContent(rawContent);

  return {
    title: title || 'Dream Job',
    content: formattedContent
  };
}

const dreamJobSections = fullText.split('---DREAM_JOB_SPLIT---');
const cleanSections = dreamJobSections.filter(section => section.trim().length > 0);

const records = cleanSections.map((section, index) => {
  const parsed = parseDreamJob(section);
  const moveMatch = section.match(/<!--move:(.*?)-->/i);
  const move = moveMatch ? moveMatch[1].trim() : null;
  const content = parsed.content.replace(/<!--move:.*?-->/gi, '').trim();

  return {
    json: {
      section_type: "dream_jobs",
      title: `<h3>${parsed.title}</h3>`,
      content: content,
      metadata: move ? { move } : null,
      report_id: reportId,
      order_number: index + 1,
      language: __lang
    }
  };
});

return records;

// Pass the original webhook payload on, so the rest of the workflow
// sees exactly what it saw before the dedupe claim was added.
return $('Encore WF3P Webhook').all();
